import {speechText} from './speech-text.mjs';
import {extraVideos} from './instrument-content.mjs';
// Original teaching sequences, grounded in the user's reference documents.
export const levels=['01 · Fundamentos','02 · Medición','03 · Señales','04 · Bloques','05 · Diagnóstico','06 · Método profesional'];
export const units=[
 {id:'nodos',level:0,title:'Del símbolo a la pista',minutes:20,mission:0,net:'GND',pattern:'pulldown',sources:[10,11],goal:'Distinguir componente, terminal y nodo; localizar la referencia en una placa real.',prerequisite:'Ninguno. Empieza aquí.',theory:[['Tres formas de ver lo mismo','El esquema representa relaciones eléctricas. El encapsulado es el cuerpo físico. La pista une terminales de un mismo nodo. Una resistencia tiene dos terminales en nodos distintos: atravesar su cuerpo no equivale a seguir una pista.'],['Referencia no significa tierra','GND es la referencia de este circuito de baja tensión. No implica necesariamente tierra de protección. La tensión se define entre dos puntos: decir «5 V» sin referencia deja la medida incompleta.'],['De la serigrafía a la conexión','R identifica normalmente resistencias, C condensadores, L bobinas y Q transistores. El número identifica la pieza, no su valor. Para reconocer una función combina referencia, terminales, red y esquema.']],example:'En la placa MOSFET, JP5.2 y Q1.3 están en GND. Están separados físicamente, pero el cobre los une. Q1.1 pertenece a CONTROL: no lo confundas con Q1.3.',trap:'Dos piezas próximas no tienen por qué estar conectadas. Un cruce de líneas tampoco demuestra una unión.',question:'¿Qué demuestra que dos pads pertenecen al mismo nodo?',answers:['Están cerca','Comparten una red eléctrica documentada','Tienen el mismo tamaño'],correct:1,why:'La conectividad determina el nodo; la posición y la forma no lo determinan.',transfer:'Busca GND en otra placa y anota dos terminales que lo compartan.',video:0},
 {id:'caras',level:0,title:'Caras, vías y encapsulados',minutes:25,mission:1,net:'CONTROL',pattern:'mosfet',sources:[3,10],goal:'Seguir una conexión al voltear la placa sin perder sus terminales.',prerequisite:'Unidad 1: componente y nodo.',theory:[['El verde y el cobre','El verde representa la máscara protectora. El modo de seguimiento deja visibles las pistas de cobre para aprender; en una placa fabricada gran parte del cobre está cubierto por máscara. Los pads expuestos permiten soldar o medir.'],['Cambiar de cara','Una vía metalizada conecta capas según el diseño. Un pad pasante puede llevar una conexión entre caras. No todas las vías atraviesan todas las capas en una placa multicapa; utiliza los datos CAD disponibles.'],['Encapsulado y pinout','THT atraviesa la placa; SMD se monta en superficie. SOIC, QFP y BGA describen familias de encapsulados. En BGA los contactos quedan ocultos: ver el cuerpo no permite reconstruir su pinout.']],example:'CONTROL conecta JP5.3, Q1.1 y R1.P$2. Selecciona la red antes de voltear y comprueba que conservas la identidad de los pads.',trap:'Voltear cambia la perspectiva, no los nombres ni la conectividad.',question:'¿Puedes deducir todas las conexiones de un BGA por su aspecto?',answers:['Sí, contando lados','No: necesitas pinout y datos de conexiones','Sí, si la placa es verde'],correct:1,why:'Los contactos están bajo el encapsulado y pueden enlazar capas internas.',transfer:'Repite el recorrido empezando en Q1.1 y terminando en el conector.',video:0},
 {id:'medir',level:1,title:'Medir con referencia e hipótesis',minutes:25,mission:2,net:'GND',pattern:'shunt',sources:[11,15,2],goal:'Preparar una comprobación de continuidad y justificarla.',prerequisite:'Unidades 1 y 2.',theory:[['Antes del número','Escribe qué mides, entre qué puntos y qué esperas. El modo V mide una diferencia de potencial; Ω y continuidad inyectan una pequeña señal de prueba. Este banco bloquea estas últimas con alimentación activa.'],['Continuidad con criterio','Un resultado bajo es compatible con un camino conductor. En un equipo real hay resistencias de puntas, umbrales del instrumento y rutas paralelas; un pitido aislado no prueba un cortocircuito defectuoso.'],['Preparación del banco','Las prácticas son virtuales y de baja tensión. En hardware, las condiciones de desconexión, descarga y protección ESD deben resolverse antes de intervenir. La protección ESD no protege de una descarga eléctrica de potencia.']],example:'Fuente OFF, modo continuidad, puntas entre JP5.2 y Q1.3. El modelo ideal devuelve 0 Ω porque ambos pads son GND.',trap:'Medir Ω con la placa alimentada invalida el procedimiento.',question:'¿Cómo preparas una medida de continuidad en este banco?',answers:['Fuente ON y modo V','Fuente OFF y modo continuidad','Da igual el modo'],correct:1,why:'La continuidad se comprueba sin tensión externa y con la función adecuada.',transfer:'Elige otra pareja de pads de GND y repite sin consultar la guía.',video:0},
 {id:'divisor',level:1,title:'El divisor: calcular antes de medir',minutes:30,mission:22,net:'OUT',pattern:'divider',sources:[9,14],goal:'Predecir y comprobar la tensión en el punto medio de dos resistencias.',prerequisite:'Tensión, resistencia y referencia.',theory:[['Una relación entre resistencias','Sin carga externa, VOUT = VIN × R2 / (R1 + R2). R2 es la resistencia entre salida y referencia. Con resistencias iguales, la mitad de la tensión cae en cada una.'],['La corriente enlaza el cálculo','Con 5 V y dos resistencias de 10 kΩ, I = 5 / 20000 = 0,25 mA. Cada resistencia cae 2,5 V. Potencia en cada una: I²R = 0,625 mW.'],['La carga cambia el divisor','Una carga desde OUT a GND queda en paralelo con R2. Si es 10 kΩ, la rama inferior equivale a 5 kΩ y OUT pasa a 1,67 V. Este es un ejemplo calculado; el banco básico usa el divisor sin esa carga adicional.']],example:'Predice 2,5 V. Abre la práctica, activa fuente y entrada alta, coloca roja en TP.OUT y negra en TP.GND.',trap:'Un divisor no es una fuente ideal de tensión independiente de la carga.',question:'Con VIN = 5 V y R1 = R2, sin carga, ¿qué esperas?',answers:['5 V','0 V','2,5 V'],correct:2,why:'R2 representa la mitad de la resistencia total.',transfer:'Calcula a mano la salida si R2 se duplica; distingue cálculo y simulación.',video:1},
 {id:'led',level:2,title:'Diodos, LED y corriente',minutes:25,mission:30,net:'OUT',pattern:'led',sources:[9,14],goal:'Obtener la corriente a partir de la caída en una resistencia.',prerequisite:'Ley de Ohm y divisor.',theory:[['El LED no fija su corriente','Un diodo tiene una característica no lineal. El modelo didáctico del LED usa una caída fija de 2 V. En un componente real la caída depende del tipo, la corriente y la temperatura.'],['Resistencia en serie','La resistencia absorbe la diferencia entre fuente y LED. Con 5 V, LED de 2 V y 1 kΩ: I = (5 − 2) / 1000 = 3 mA. Sin limitación de corriente puedes dañar un LED real.'],['Medición indirecta','Mide la caída entre extremos de R1 y divídela por su resistencia. Evitas abrir la rama para insertar un amperímetro. El resultado depende de conocer el valor real y la tolerancia.']],example:'En el banco LED, R1.1 menos R1.2 da 3 V en el modelo. Esa caída corresponde a 3 mA.',trap:'Medir 5 V en la alimentación no significa que el LED esté conduciendo.',question:'Si caen 3 V en 1 kΩ, ¿qué corriente circula?',answers:['3 A','3 mA','0,3 mA'],correct:1,why:'3 / 1000 A = 0,003 A = 3 mA.',transfer:'Compara después la avería LED abierto y explica por qué desaparece la corriente.',video:1},
 {id:'rc',level:2,title:'Condensadores y señales en el tiempo',minutes:35,mission:28,net:'OUT',pattern:'rc-low',sources:[9,5,6],goal:'Relacionar una carga RC con una curva y una medida sobre la placa.',prerequisite:'Divisor y medición de tensión.',theory:[['Almacenar energía','Un condensador almacena energía en su campo eléctrico. Su tensión no cambia instantáneamente en el modelo ideal con corriente finita. Al conectarlo mediante una resistencia aparece una evolución temporal.'],['Una escala de tiempo','τ = R × C. Con 10 kΩ y 100 nF, τ = 1 ms. Desde cero hacia 5 V: V(t) = 5 × (1 − e^(−t/τ)). A 1τ alcanza el 63,2 %, a 3τ el 95 % y a 5τ el 99,3 %; no se carga exactamente por completo en un tiempo finito.'],['Del tiempo a la frecuencia','Un RC pasa-bajos atenúa frecuencias altas. fc = 1 / (2πRC), unos 159 Hz para estos valores. En el osciloscopio puedes comparar entrada y salida; comprueba R y C porque sus valores iniciales pueden ser distintos.']],example:'En la práctica de 5 ms, espera aproximadamente 4,966 V. Luego cambia a 1 ms para comparar con 3,161 V.',trap:'«Prácticamente cargado» depende de la tolerancia que aceptes; 3τ no significa 100 %.',question:'¿Qué porcentaje alcanza la carga ideal a 1τ?',answers:['100 %','63,2 %','10 %'],correct:1,why:'1 − e^(−1) equivale aproximadamente a 0,632.',transfer:'En Osciloscopio compara un seno antes y después de un filtro RC.',video:1},
 {id:'mosfet',level:3,title:'Separar mando y potencia',minutes:35,mission:4,net:'CONTROL',pattern:'mosfet',sources:[13,14,9],goal:'Reconocer puerta, fuente y drenador; medir VGS.',prerequisite:'Diferencia de potencial y ley de Ohm.',theory:[['Dos recorridos distintos','El mando fija el estado del transistor. El recorrido de potencia alimenta la carga. En este interruptor NMOS de lado bajo, la carga está entre VCC y drenador; la fuente retorna a GND.'],['La magnitud de control','VGS es tensión de puerta respecto a fuente, no siempre respecto a masa. La tensión umbral no garantiza conducción con baja resistencia: esa condición se comprueba en la ficha técnica a la tensión de mando disponible.'],['Pérdidas y alcance','En conducción, una aproximación es P = I² × RDS(on). En equipos conmutados se añaden pérdidas durante las transiciones. El banco usa un modelo DC simplificado y no calcula temperatura ni pérdidas de conmutación.']],example:'Punta roja Q1.1, negra Q1.3. Con alimentación y CONTROL alto, VGS = 5 V.',trap:'Puerta alta respecto a tierra no garantiza VGS alto si la fuente también está elevada.',question:'¿Entre qué terminales se mide VGS?',answers:['Drenador y tierra','Puerta y fuente','Puerta y drenador'],correct:1,why:'La propia notación VGS indica puerta (G) respecto a fuente (S).',transfer:'Compara después la caída drenador-fuente con mando alto y bajo.',video:2},
 {id:'digital',level:3,title:'Niveles lógicos y microcontroladores',minutes:30,mission:7,net:'HV1',pattern:'pullup',sources:[8,4],goal:'Distinguir señal, alimentación y referencia en un conversor lógico.',prerequisite:'MOSFET y referencia de medida.',theory:[['Digital sigue siendo eléctrico','Un 0 o un 1 lógico corresponde a intervalos de tensión definidos por el dispositivo. 3,3 V y 5 V no son intercambiables por defecto. Consulta límites de entrada y umbrales antes de conectar hardware.'],['El papel del pull-up','Una resistencia lleva una línea liberada a su alimentación. Si un transistor conduce hacia GND, puede imponer un nivel bajo. Compartir una alimentación no convierte dos canales de señal en una misma red.'],['Secuencia de arranque','En sistemas microprogramables, revisa alimentación, reset, reloj y después actividad de señales. Ver una línea alta en DC no demuestra que haya comunicación ni que el firmware funcione.']],example:'En el conversor en reposo, HV1 = 5 V y LV1 = 3,3 V. Medidos uno respecto al otro dan 1,7 V.',trap:'Una diferencia de 1,7 V entre señales no significa que la alimentación sea de 1,7 V.',question:'¿Qué prueba una tensión DC alta en un bus?',answers:['Que el programa funciona','Solo el nivel en ese instante, no la comunicación','Que todos los canales están unidos'],correct:1,why:'Para evaluar actividad y temporización hacen falta medidas en el tiempo.',transfer:'Sigue un segundo canal sin confundirlo con el primero.',video:2},
 {id:'diagnostico',level:4,title:'Del síntoma a una prueba decisiva',minutes:40,mission:6,net:'HIGH-CURRENT',pattern:'mosfet',sources:[11,15,12],goal:'Contrastar dos hipótesis antes de declarar un componente averiado.',prerequisite:'Mando y potencia; medición en dos estados.',theory:[['Formula el síntoma','«La salida no sube con mando bajo» describe una observación. «MOSFET roto» es una hipótesis. Separarlas evita sustituir piezas sin pruebas y permite reproducir el problema.'],['Elige una prueba que discrimine','Si la salida está a cero, podría existir conducción no deseada o un corto externo. Comprobar VGS descarta que el mando siga alto. En hardware aún hace falta separar caminos; la simulación identifica una avería inyectada concreta.'],['Cierra el diagnóstico','Registra estado, puntos, modo, valor esperado, valor observado e interpretación. Tras reparar, repite las mismas condiciones y comprueba también el estado contrario. Un resultado correcto aislado no verifica todo el equipo.']],example:'Con avería Q1 en corto, CONTROL bajo y fuente activa, el drenador permanece a 0 V. Elige el diagnóstico coherente en el banco.',trap:'Un nodo a 0 V por sí solo no identifica qué pieza causó el corto.',question:'¿Cuál es una conclusión técnicamente prudente?',answers:['0 V demuestra siempre Q1 roto','0 V exige contrastar mando y caminos alternativos','Cambiar todas las piezas'],correct:1,why:'Una medida debe interpretarse con el estado del circuito y con hipótesis alternativas.',transfer:'Escribe qué segunda comprobación necesitarías en un equipo físico.',video:2},
 {id:'bloques',level:4,title:'Audio, vídeo y lectura por bloques',minutes:40,mission:43,net:'5V_MAIN',pattern:'noninv',sources:[5,6,7,11],goal:'Separar alimentación, señal y salida en una arquitectura de TV.',prerequisite:'Recorridos de energía y señal.',theory:[['La arquitectura reduce el problema','Un equipo puede agrupar entrada, acondicionamiento, procesamiento y salida en una misma placa. La división funcional no exige separaciones físicas. Sigue conectores y redes para confirmar cada bloque.'],['Audio: amplitud y recorrido','En una cadena de audio distingue señal pequeña, amplificación y carga. La ganancia de tensión en dB es 20 log10(Vout/Vin); 2× son unos 6 dB. No confundas ganancia eléctrica y nivel de presión sonora.'],['Vídeo: imagen y control','La ruta de imagen y la de retroiluminación son diferentes. En la placa TV didáctica, 5V_MAIN es una alimentación; BL_EN y BL_PWM son controles. Su existencia no acredita una imagen válida ni una retroiluminación encendida.']],example:'Localiza 5V_MAIN y compara sus terminales con los de BL_PWM. Relaciona regulador, control y carga antes de atribuirles una función.',trap:'Una pantalla oscura no equivale automáticamente a ausencia de vídeo.',question:'¿Una misma placa puede contener varios bloques funcionales?',answers:['Sí; los distinguen sus funciones y conexiones','No; un bloque siempre es una placa separada','Solo si tienen distinto color'],correct:0,why:'La división funcional es una herramienta de análisis, no una división mecánica obligatoria.',transfer:'Dibuja un árbol de dos causas para «pantalla sin imagen» y qué evidencia las separaría.',video:2},
 {id:'multicapa',level:5,title:'Placas multicapa: investigar sin adivinar',minutes:45,mission:40,net:'GND',pattern:'decoupling',sources:[3,4,16],goal:'Documentar una ruta y sus límites en una placa de ordenador.',prerequisite:'Todas las unidades de fundamentos y bloques.',theory:[['Trabaja con dominios','Una placa de ordenador tiene varios raíles y señales de distinta velocidad. Agrupa alimentación, memoria, procesamiento e interfaces y elige un bloque limitado. No intentes deducir todo por proximidad.'],['Desacoplo y retorno','Un condensador entre alimentación y referencia puede ofrecer una ruta local a corrientes transitorias. Su colocación y el recorrido de retorno importan. En alta frecuencia, una conexión real tiene resistencia, inductancia y capacitancia.'],['Evidencia y límites','El CAD permite consultar conexiones internas documentadas. No aporta por sí solo una simulación de arranque, ruido o estabilidad. Las prácticas de la placa de ordenador verifican conectividad y razonamiento, no tensiones operativas calculadas.']],example:'Selecciona GND, consulta sus pads y una capa interna. Distingue contorno de plano de cobre y pista: el visor no reconstruye todos los alivios térmicos.',trap:'Un plano dibujado con contorno no prueba que toda el área interior sea cobre continuo fabricable.',question:'¿Qué puedes concluir únicamente de una red CAD?',answers:['Que el procesador arranca','Sus conexiones documentadas','Que la fuente no tiene ruido'],correct:1,why:'La conectividad no demuestra el comportamiento dinámico del equipo.',transfer:'Registra una incertidumbre que solo podrías resolver con esquema, ficha técnica o medición adicional.',video:0},
 {id:'informe',level:5,title:'Un diagnóstico que otro técnico pueda repetir',minutes:45,mission:41,net:'GND',pattern:'comparator',sources:[12,11,1,2,16],goal:'Redactar una hipótesis, una medida reproducible y un criterio de aceptación.',prerequisite:'Diagnóstico y placas multicapa.',theory:[['Repetibilidad','Una nota útil identifica equipo y revisión, síntoma, condiciones, puntos, instrumento, resultado y límites. «Parece bien» no permite a otra persona repetir tu análisis.'],['Secuencias y control','En automatización distingue estado, acción y transición. La página de GRAFCET aportada recuerda la alternancia de etapas y transiciones. Un fallo de secuencia exige comprobar condiciones y entradas, además de componentes físicos.'],['Calidad de la conclusión','Distingue observado, calculado e inferido. Define una prueba posterior a la intervención y un criterio de aceptación. Aquí el razonamiento escrito se guarda como evidencia personal; no se certifica competencia profesional presencial.']],example:'En metodología, paso 6: escribe qué tensión esperarías, entre qué puntos y bajo qué condición de arranque; añade qué revisarías si difiere. El reto comprueba el registro, no la exactitud de una tensión no simulada.',trap:'Un informe largo sin condiciones de prueba sigue sin ser reproducible.',question:'¿Qué debe acompañar a una medida anotada?',answers:['Solo el número','Puntos, condiciones, unidades e interpretación','Solo una foto del equipo'],correct:1,why:'Esos datos permiten repetir y cuestionar la prueba.',transfer:'Repite el informe para una segunda placa y compara qué datos todavía faltan.',video:2}
];
export const videos=[
 {id:'pistas',title:'Una red, dos caras',description:'Del terminal al cobre: gira la placa y conserva la identidad de la red. Modelo geométrico didáctico.',chapters:['Localizar','Seleccionar','Voltear','Comprobar'],transcript:['Localiza los terminales de una misma red. La distancia física no define la conexión.','El cobre iluminado muestra el recorrido seleccionado. La animación es una guía visual, no el movimiento de electrones.','Al voltear, los pads pasantes conservan su identidad. En esta red CONTROL los tramos están en la cara superior: no inventes una pista inferior para unir los pads.','Comprueba el nombre de red y sus terminales antes de cambiar a otra conexión.']},
 {id:'divisor',title:'El divisor sobre una placa',description:'Dos resistencias, tres nodos y una predicción de 2,5 V. Ejemplo ideal sin carga.',chapters:['Identificar','Predecir','Seguir OUT','Interpretar'],transcript:['Identifica R1 entre VIN y OUT, y R2 entre OUT y GND.','Con 5 V y dos resistencias iguales, la salida sin carga es 2,5 V.','La pista iluminada OUT une las dos resistencias y el punto de medida.','Mide OUT respecto a GND. Una carga añadida modifica el resultado del divisor.']},
 {id:'mando',title:'Mando y recorrido de potencia',description:'Separación visual del control y la energía en un interruptor MOSFET de lado bajo.',chapters:['Bloques','Mando','Potencia','Diagnóstico'],transcript:['Distingue el conector de mando, el transistor y la conexión hacia la carga.','La puerta se controla respecto a la fuente: observa la red CONTROL.','La energía de la carga sigue un recorrido distinto del mando. La animación muestra conectividad, no una simulación de corriente.','Una salida inesperada requiere comprobar el mando y contrastar hipótesis antes de culpar a una pieza.']}
];

videos.push(...extraVideos);

for(const video of videos)if(speechText[video.id])video.transcript=speechText[video.id];
